import type { Directive } from 'vue'
import { useComfierLayoutStore } from './layoutStore'
import { useComfierPanelStore } from './panelStore'
const cleanup = new WeakMap<HTMLElement, () => void>()
export const vLayoutControl: Directive<HTMLElement, string> = {
  mounted(el, { value }) {
    useComfierLayoutStore().register(value, el)
    const launch = () =>
      useComfierPanelStore().launchFrom(el.getBoundingClientRect())
    el.addEventListener('click', launch, { capture: true })
    cleanup.set(el, () =>
      el.removeEventListener('click', launch, { capture: true })
    )
  },
  updated(el, { value, oldValue }) {
    if (oldValue && oldValue !== value)
      useComfierLayoutStore().unregister(oldValue, el)
    useComfierLayoutStore().register(value, el)
  },
  unmounted(el, { value }) {
    cleanup.get(el)?.()
    cleanup.delete(el)
    useComfierLayoutStore().unregister(value, el)
  }
}
